rder:1px solid #3a4434;border-radius:8px;background:linear-gradient(105deg,#20271c,#1b211a 65%,#21291d);overflow:hidden}.token-banner:after{content:'✦';position:absolute;right:215px;top:-35px;font-size:145px;color:rgba(200,241,105,.035);pointer-events:none}.token-emblem{width:46px;height:46px;flex:0 0 46px;display:grid;place-items:center;border-radius:50%;border:1px solid #657748;color:var(--lime);font-size:23px;background:rgba(200,241,105,.06)}.token-message{flex:1;min-width:0}.token-message .eyebrow{margin-bottom:3px;color:#95a77b;font-size:9px}.token-message h2{font-size:20px}.token-message p{margin:4px 0 0;color:#a2ab9d;font-size:11px}.token-button{position:relative;z-index:1;white-space:nowrap;height:42px;padding:0 17px;border:1px solid var(--lime);border-radius:5px;background:var(--lime);color:#1a2412;font:700 12px var(--font);cursor:pointer;transition:.2s}.token-button:hover{background:#d6ff83;box-shadow:0 0 20px rgba(200,241,105,.15)}.token-button span{font-size:15px;margin-right:5px}.token-banner.won{border-color:#5c854f;background:linear-gradient(105deg,#202b20,#20271c)}.token-banner.won .token-emblem{color:#132011;background:var(--lime)}.token-banner.won .token-button{background:transparent;color:var(--lime)}.footer-note{display:flex;align-items:center;gap:9px;margin:17px 0 0;color:#7f897c;font-size:10px}.info-icon{width:14px;height:14px;display:grid;place-items:center;border:1px solid #697566;border-radius:50%;font:9px var(--mono);color:#a8b2a5}.footer-divider{height:12px;width:1px;background:#394137;margin:0 4px}.setup-layer{position:fixed;inset:0;z-index:5;display:grid;place-items:center;padding:24px;overflow-y:auto}.setup-backdrop{position:fixed;inset:0;background:rgba(7,10,7,.82);backdrop-filter:blur(8px)}.setup-card{position:relative;z-index:1;width:min(100%,472px);padding:33px 38px 27px;border:1px solid #3b4636;border-radius:10px;background:linear-gradient(145deg,#1c241c,#151b16);box-shadow:0 25px 100px rgba(0,0,0,.5)}.setup-close{position:absolute;right:15px;top:14px;width:30px;height:30px;border:1px solid #3b4638;background:transparent;border-radius:4px;color:#aab4a6;font-size:22px;cursor:pointer}.setup-kicker{display:flex;align-items:center;gap:8px;font:10px var(--mono);letter-spacing:.13em;color:#95a08f;margin-bottom:34px}.setup-card>.eyebrow{margin-bottom:12px}.setup-card h2{font:900 46px/.91 var(--display);letter-spacing:-.015em;margin-bottom:12px}.setup-card h2 span{color:var(--lime)}.setup-copy{font-size:13px;color:#a1ab9f;line-height:1.55;margin-bottom:23px}.field-label{display:block;color:#d4dbd0;font-size:11px;font-weight:600;margin:0 0 7px}.input-wrap{position:relative;margin-bottom:17px}.input-wrap input{width:100%;height:45px;padding:0 75px 0 13px;border:1px solid #394437;border-radius:5px;outline:none;background:#111711;color:var(--text);font:500 15px var(--mono);appearance:textfield}.input-wrap input::-webkit-inner-spin-button,.input-wrap input::-webkit-outer-spin-button{appearance:none}.input-wrap input:focus{border-color:var(--lime-dark);box-shadow:0 0 0 2px rgba(200,241,105,.08)}.input-wrap>span{position:absolute;right:13px;top:16px;color:#697666;font:9px var(--mono);letter-spacing:.1em}.setup-hint{margin:-5px 0 17px;color:#7f8a7c;font-size:10px}.primary-button{height:46px;width:100%;display:flex;align-items:center;justify-content:space-between;padding:0 15px;border:0;border-radius:5px;background:var(--lime);color:#182012;font:700 12px var(--font);cursor:pointer}.primary-button:hover{background:#d9ff87}.primary-button span:last-child{font-size:17px}.setup-privacy{font-size:9px;margin:17px 0 0;text-align:center;letter-spacing:.02em}.setup-privacy .online-dot{width:6px;height:6px}.toast{position:fixed;z-index:10;bottom:24px;left:50%;transform:translate(-50%,15px);padding:11px 16px;border:1px solid #4d5e43;border-radius:5px;background:#222d20;color:#e3eedb;font-size:12px;opacity:0;pointer-events:none;transition:.24s;white-space:nowrap}.toast.show{opacity:1;transform:translate(-50%,0)}[hidden]{